class Solution:
    def minCost(self, grid: list[list[int]]) -> int:
        m, n = len(grid), len(grid[0])
        mx = 1 << (max(max(row) for row in grid)).bit_length()
        f = [[[False] * mx for _ in range(n)] for _ in range(m)]
        f[0][0][grid[0][0]] = True
        for i, row in enumerate(grid):
            for j, x in enumerate(row):
                if i > 0 or j > 0:
                    for k in range(mx):
                        if i > 0 and f[i - 1][j][k ^ x]:
                            f[i][j][k] = True
                        if j > 0 and f[i][j - 1][k ^ x]:
                            f[i][j][k] = True
        return next(k for k in range(mx) if f[m - 1][n - 1][k])

class Solution {
    public int minCost(int[][] grid) {
        int m = grid.length, n = grid[0].length;
        int mx = 0;
        for (int[] row : grid) {
            for (int x : row) {
                mx = Math.max(mx, x);
            }
        }
        mx = 1 << (Integer.SIZE - Integer.numberOfLeadingZeros(mx));
        boolean[][][] f = new boolean[m][n][mx];
        f[0][0][grid[0][0]] = true;
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                int x = grid[i][j];
                if (i > 0 || j > 0) {
                    for (int k = 0; k < mx; k++) {
                        if (i > 0 && f[i - 1][j][k ^ x]) {
                            f[i][j][k] = true;
                        }
                        if (j > 0 && f[i][j - 1][k ^ x]) {
                            f[i][j][k] = true;
                        }
                    }
                }
            }
        }
        for (int k = 0;; k++) {
            if (f[m - 1][n - 1][k]) {
                return k;
            }
        }
    }
}

